      const checkboxRef = useRef(null);

      const handleSubmit = (e) => {
        e.preventDefault();

        // Manual validation handling
        if (!agreed) {
          setError(true);
          checkboxRef.current?.focus();
        } else {
          setError(false);
          // Simulate form submission
          alert('Agreement accepted. Form submitted successfully!');
        }
      };

