        const checked = e.target.checked;
        setAgreed(checked);

        // Clear error as soon as user checks the box
        if (checked && error) {
          setError(false);
        }
      };

      // Construct aria-describedby based on error state
      const ariaDescribedBy = [];
      if (error) ariaDescribedBy.push('consent-error');
      ariaDescribedBy.push('consent-helper');

      return (
        <div className="form-container">
          <h2>Terms & Conditions</h2>

          <form onSubmit={handleSubmit} noValidate>

            <div className="form-field">
              <div className="checkbox-wrapper">
