                  type="checkbox"
                  id="consent-checkbox"
                  ref={checkboxRef}
                  checked={agreed}
                  onChange={handleChange}
                  required
                  aria-invalid={error ? "true" : undefined}
                  aria-describedby={ariaDescribedBy.join(' ')}
                />

                <label htmlFor="consent-checkbox" className="label-text">
                  I agree to the Terms of Use
                  <span className="required-marker" aria-hidden="true" title="Required">*</span>
                </label>
              </div>

              <p id="consent-helper" className="helper-text">
                By checking this box, you agree to our terms of use and privacy policy.
              </p>

              {error && (
                <p id="consent-error" className="error-text" role="alert">
                  Error: You must check this box to submit the form.
                </p>
              )}
            </div>

            <button type="submit">Submit Agreement</button>

          </form>
        </div>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ConsentForm />);
  </script>
