      const handleSubmit = (e) => {
        e.preventDefault();

        // Manual validation handling
        if (!agreed) {
          setError(true);
          checkboxRef.current?.focus();
        } else {
          setError(false);
          // Simulate form submission
          alert('Agreement accepted. Form submitted successfully!');
        }
      };

      const handleChange = (e) => {
        const checked = e.target.checked;
        setAgreed(checked);

        // Clear error as soon as user checks the box
        if (checked && error) {
          setError(false);
        }
      };

      // Construct aria-describedby based on error state
      const ariaDescribedBy = [];
      if (error) ariaDescribedBy.push('consent-error');
      ariaDescribedBy.push('consent-helper');

      return (
        <main className="form-container">
          <h1>Terms & Conditions</h1>

          <form onSubmit={handleSubmit} noValidate>

            <div className="form-field">
              <div className="checkbox-wrapper">
                <input
                  type="checkbox"
                  id="consent-checkbox"
                  ref={checkboxRef}
                  checked={agreed}
                  onChange={handleChange}
                  required
                  aria-invalid={error ? "true" : undefined}
                  aria-describedby={ariaDescribedBy.join(' ')}
                />

                <label htmlFor="consent-checkbox" className="label-text">
                  I agree to the Terms of Use
                  <span className="required-marker" aria-hidden="true" title="Required">*</span>
                </label>
              </div>

              <p id="consent-helper" className="helper-text">
                By checking this box, you agree to our terms of use and privacy policy.
              </p>

              {error && (
                <p id="consent-error" className="error-text" role="alert">
                  Error: You must check this box to submit the form.
                </p>
              )}
            </div>

            <button type="submit">Submit Agreement</button>

          </form>
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ConsentForm />);
  </script>
</body>
